--
-- Table structure for table `currentstocklots`
--

DROP TABLE IF EXISTS `currentstocklots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `currentstocklots` (
  `lotStockId` binary(16) NOT NULL,
  `warehouseId` binary(16) NOT NULL,
  `ingredientId` binary(16) NOT NULL,
  `unitId` binary(16) NOT NULL,
  `lotNumber` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufactureDate` date DEFAULT NULL,
  `expiredDate` date DEFAULT NULL,
  `currentQty` decimal(18,6) NOT NULL DEFAULT '0.000000',
  `lastUpdated` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`lotStockId`),
  KEY `currentstocklots_ibfk_2` (`ingredientId`),
  KEY `currentstocklots_ibfk_3` (`unitId`),
  KEY `ixCurrentStockLotsFefo` (`warehouseId`,`ingredientId`,`expiredDate`,`lotNumber`),
  KEY `ixCurrentStockLotsIdentity` (`warehouseId`,`ingredientId`,`unitId`,`lotNumber`,`manufactureDate`,`expiredDate`),
  CONSTRAINT `currentstocklots_ibfk_1` FOREIGN KEY (`warehouseId`) REFERENCES `warehouses` (`warehouseId`),
  CONSTRAINT `currentstocklots_ibfk_2` FOREIGN KEY (`ingredientId`) REFERENCES `ingredients` (`ingredientId`),
  CONSTRAINT `currentstocklots_ibfk_3` FOREIGN KEY (`unitId`) REFERENCES `units` (`unitId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

