--
-- Table structure for table `ingredients`
--

DROP TABLE IF EXISTS `ingredients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ingredients` (
  `ingredientId` binary(16) NOT NULL,
  `ingredientCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ingredientName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `unitId` binary(16) NOT NULL,
  `warehouseId` binary(16) NOT NULL,
  `referencePrice` decimal(18,2) NOT NULL DEFAULT '0.00',
  `isFreshDaily` tinyint(1) NOT NULL DEFAULT '0',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`ingredientId`),
  UNIQUE KEY `ingredientCode` (`ingredientCode`),
  KEY `unitId` (`unitId`),
  KEY `warehouseId` (`warehouseId`),
  CONSTRAINT `ingredients_ibfk_1` FOREIGN KEY (`unitId`) REFERENCES `units` (`unitId`),
  CONSTRAINT `ingredients_ibfk_2` FOREIGN KEY (`warehouseId`) REFERENCES `warehouses` (`warehouseId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ingredients`
--

LOCK TABLES `ingredients` WRITE;
