--
-- Table structure for table `inventoryreceiptlines`
--

DROP TABLE IF EXISTS `inventoryreceiptlines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventoryreceiptlines` (
  `receiptLineId` binary(16) NOT NULL,
  `receiptId` binary(16) NOT NULL,
  `ingredientId` binary(16) NOT NULL,
  `unitId` binary(16) NOT NULL,
  `quantity` decimal(18,6) NOT NULL DEFAULT '0.000000',
  `unitPrice` decimal(18,2) NOT NULL DEFAULT '0.00',
  `amount` decimal(18,2) GENERATED ALWAYS AS ((`quantity` * `unitPrice`)) STORED,
  `lotNumber` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufactureDate` date DEFAULT NULL,
  `expiredDate` date DEFAULT NULL,
  `purchaseRequestLineId` binary(16) DEFAULT NULL,
  `packageBaseUnitIdSnapshot` binary(16) DEFAULT NULL,
  `packagePolicyVersionSnapshot` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `packageQuantitySnapshot` decimal(18,6) DEFAULT NULL,
  `acceptedQuantity` decimal(18,6) DEFAULT NULL,
  `qualityReason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rejectedQuantity` decimal(18,6) DEFAULT NULL,
  `purchaseOrderLineId` binary(16) DEFAULT NULL,
  PRIMARY KEY (`receiptLineId`),
  KEY `receiptId` (`receiptId`),
  KEY `unitId` (`unitId`),
  KEY `ixInventoryReceiptLinesExpiry` (`ingredientId`,`expiredDate`,`lotNumber`),
  KEY `purchaseRequestLineId` (`purchaseRequestLineId`),
  KEY `IX_inventoryreceiptlines_packageBaseUnitIdSnapshot` (`packageBaseUnitIdSnapshot`),
  KEY `ixInventoryReceiptLinesPurchaseOrderLine` (`purchaseOrderLineId`),
  CONSTRAINT `inventoryreceiptlines_ibfk_1` FOREIGN KEY (`receiptId`) REFERENCES `inventoryreceipts` (`receiptId`),
  CONSTRAINT `inventoryreceiptlines_ibfk_2` FOREIGN KEY (`ingredientId`) REFERENCES `ingredients` (`ingredientId`),
  CONSTRAINT `inventoryreceiptlines_ibfk_3` FOREIGN KEY (`unitId`) REFERENCES `units` (`unitId`),
  CONSTRAINT `inventoryreceiptlines_ibfk_4` FOREIGN KEY (`purchaseRequestLineId`) REFERENCES `purchaserequestlines` (`purchaseRequestLineId`),
  CONSTRAINT `inventoryreceiptlines_ibfk_5` FOREIGN KEY (`packageBaseUnitIdSnapshot`) REFERENCES `units` (`unitId`) ON DELETE RESTRICT,
  CONSTRAINT `inventoryreceiptlines_ibfk_6` FOREIGN KEY (`purchaseOrderLineId`) REFERENCES `purchaseorderlines` (`purchaseOrderLineId`) ON DELETE RESTRICT,
  CONSTRAINT `ckInventoryReceiptLinesPackageQuantityPositive` CHECK (((`packageQuantitySnapshot` is null) or (`packageQuantitySnapshot` > 0))),
  CONSTRAINT `ckInventoryReceiptLinesPackageSnapshotComplete` CHECK ((((`packageQuantitySnapshot` is null) and (`packageBaseUnitIdSnapshot` is null) and (`packagePolicyVersionSnapshot` is null)) or ((`packageQuantitySnapshot` is not null) and (`packageBaseUnitIdSnapshot` is not null) and (`packagePolicyVersionSnapshot` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

