/*!40000 ALTER TABLE `inventoryreceiptlines` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `inventoryreceipts`
--

DROP TABLE IF EXISTS `inventoryreceipts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventoryreceipts` (
  `receiptId` binary(16) NOT NULL,
  `receiptCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `receiptDate` date NOT NULL,
  `warehouseId` binary(16) NOT NULL,
  `supplierId` binary(16) NOT NULL,
  `purchaseRequestId` binary(16) DEFAULT NULL,
  `createdBy` binary(16) NOT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `concurrencyVersion` bigint NOT NULL DEFAULT '0',
  `managerApprovalReason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `managerApprovedAt` datetime DEFAULT NULL,
  `managerApprovedBy` binary(16) DEFAULT NULL,
  `postedAt` datetime DEFAULT NULL,
  `postedBy` binary(16) DEFAULT NULL,
  `qualityStatus` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_INSPECTION',
  `rejectedAt` datetime DEFAULT NULL,
  `rejectedBy` binary(16) DEFAULT NULL,
  `rejectionReason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `purchaseOrderId` binary(16) DEFAULT NULL,
  `qualityCheckedAt` datetime DEFAULT NULL,
  `qualityCheckedBy` binary(16) DEFAULT NULL,
  PRIMARY KEY (`receiptId`),
  UNIQUE KEY `receiptCode` (`receiptCode`),
  KEY `warehouseId` (`warehouseId`),
  KEY `supplierId` (`supplierId`),
  KEY `purchaseRequestId` (`purchaseRequestId`),
  KEY `createdBy` (`createdBy`),
  KEY `ixInventoryReceiptsLifecycle` (`status`,`qualityStatus`,`createdAt`),
  KEY `ixInventoryReceiptsPurchaseOrder` (`purchaseOrderId`),
  CONSTRAINT `inventoryreceipts_ibfk_1` FOREIGN KEY (`warehouseId`) REFERENCES `warehouses` (`warehouseId`),
  CONSTRAINT `inventoryreceipts_ibfk_2` FOREIGN KEY (`supplierId`) REFERENCES `suppliers` (`supplierId`),
  CONSTRAINT `inventoryreceipts_ibfk_3` FOREIGN KEY (`purchaseRequestId`) REFERENCES `purchaserequests` (`purchaseRequestId`),
  CONSTRAINT `inventoryreceipts_ibfk_4` FOREIGN KEY (`createdBy`) REFERENCES `users` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `inventoryreceipts`
--

LOCK TABLES `inventoryreceipts` WRITE;
/*!40000 ALTER TABLE `inventoryreceipts` DISABLE KEYS */;
