  PRIMARY KEY (`requestId`),
  UNIQUE KEY `requestCode` (`requestCode`),
  KEY `createdBy` (`createdBy`),
  KEY `approvedBy` (`approvedBy`),
  KEY `ixMaterialRequestsPlan` (`planId`,`status`),
  CONSTRAINT `materialrequests_ibfk_1` FOREIGN KEY (`planId`) REFERENCES `productionplans` (`planId`),
  CONSTRAINT `materialrequests_ibfk_2` FOREIGN KEY (`createdBy`) REFERENCES `users` (`userId`),
  CONSTRAINT `materialrequests_ibfk_3` FOREIGN KEY (`approvedBy`) REFERENCES `users` (`userId`)
