DROP TABLE IF EXISTS `mealquantityplans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mealquantityplans` (
  `quantityPlanId` binary(16) NOT NULL,
  `importBatchId` binary(16) DEFAULT NULL,
  `planCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `serviceDate` date NOT NULL,
  `status` enum('DRAFT','FORECASTED','CONFIRMED','ADJUSTED','COMPLETED','CANCELLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `forecastReceivedAt` datetime DEFAULT NULL,
  `confirmedAt` datetime DEFAULT NULL,
  `confirmationTime` time NOT NULL DEFAULT '08:30:00',
  `confirmedBy` binary(16) DEFAULT NULL,
  `completedAt` datetime DEFAULT NULL,
  `completedBy` binary(16) DEFAULT NULL,
  `rowVersion` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`quantityPlanId`),
  UNIQUE KEY `planCode` (`planCode`),
  KEY `importBatchId` (`importBatchId`),
  KEY `confirmedBy` (`confirmedBy`),
  KEY `ixMealQuantityPlansDate` (`serviceDate`,`status`,`confirmedAt`),
  KEY `IX_mealquantityplans_completedBy` (`completedBy`),
  CONSTRAINT `mealquantityplans_ibfk_1` FOREIGN KEY (`importBatchId`) REFERENCES `quantityimportbatches` (`importBatchId`),
  CONSTRAINT `mealquantityplans_ibfk_2` FOREIGN KEY (`confirmedBy`) REFERENCES `users` (`userId`),
  CONSTRAINT `mealquantityplans_ibfk_3` FOREIGN KEY (`completedBy`) REFERENCES `users` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
