--
-- Table structure for table `menuschedules`
--

DROP TABLE IF EXISTS `menuschedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `menuschedules` (
  `menuScheduleId` binary(16) NOT NULL,
  `customerId` binary(16) NOT NULL,
  `menuId` binary(16) NOT NULL,
  `serviceDate` date NOT NULL,
  `weekStartDate` date NOT NULL,
  `shiftName` enum('MORNING','AFTERNOON') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `menuPrice` decimal(18,2) NOT NULL DEFAULT '0.00',
  `bomRatePercent` decimal(5,2) NOT NULL DEFAULT '100.00',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `menuVersionId` binary(16) DEFAULT NULL,
  PRIMARY KEY (`menuScheduleId`),
  UNIQUE KEY `uqMenuSchedulesCustomerDateShift` (`customerId`,`serviceDate`,`shiftName`),
  KEY `menuId` (`menuId`),
  KEY `ixMenuSchedulesWeek` (`weekStartDate`,`serviceDate`,`shiftName`,`customerId`),
  KEY `IX_menuschedules_menuVersionId` (`menuVersionId`),
  KEY `ixMenuSchedulesCustomerWeek` (`customerId`,`weekStartDate`),
  CONSTRAINT `menuschedules_customerweek_tier_fk` FOREIGN KEY (`customerId`, `weekStartDate`) REFERENCES `customerweekmenutiers` (`customerId`, `weekStartDate`) ON DELETE RESTRICT,
  CONSTRAINT `menuschedules_ibfk_1` FOREIGN KEY (`customerId`) REFERENCES `customers` (`customerId`),
  CONSTRAINT `menuschedules_ibfk_2` FOREIGN KEY (`menuId`) REFERENCES `menus` (`menuId`),
  CONSTRAINT `menuschedules_ibfk_3` FOREIGN KEY (`menuVersionId`) REFERENCES `menuversions` (`menuVersionId`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `menuschedules`
--

LOCK TABLES `menuschedules` WRITE;
