--
-- Table structure for table `menuversions`
--

DROP TABLE IF EXISTS `menuversions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `menuversions` (
  `menuVersionId` binary(16) NOT NULL,
  `customerId` binary(16) NOT NULL,
  `weekStartDate` date NOT NULL,
  `versionNo` int NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `sourceFileName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourceChecksum` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourceImportBatch` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdBy` binary(16) DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `publishedBy` binary(16) DEFAULT NULL,
  `publishedAt` datetime DEFAULT NULL,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `successRowCount` int NOT NULL DEFAULT '0',
  `errorRowCount` int NOT NULL DEFAULT '0',
  `warningRowCount` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`menuVersionId`),
  UNIQUE KEY `uqMenuVersionsCustomerWeekVersion` (`customerId`,`weekStartDate`,`versionNo`),
  KEY `customerId` (`customerId`),
  KEY `ixMenuVersionsCustomerWeekStatus` (`customerId`,`weekStartDate`,`status`),
  CONSTRAINT `menuversions_ibfk_1` FOREIGN KEY (`customerId`) REFERENCES `customers` (`customerId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

