  `customerId` binary(16) NOT NULL,
  `menuId` binary(16) NOT NULL,
  `dishId` binary(16) NOT NULL,
  `shiftName` enum('MORNING','AFTERNOON') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `totalServings` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`planLineId`),
  KEY `planId` (`planId`),
  KEY `quantityPlanLineId` (`quantityPlanLineId`),
  KEY `customerId` (`customerId`),
  KEY `menuId` (`menuId`),
  KEY `dishId` (`dishId`),
  CONSTRAINT `productionplanlines_ibfk_1` FOREIGN KEY (`planId`) REFERENCES `productionplans` (`planId`),
  CONSTRAINT `productionplanlines_ibfk_2` FOREIGN KEY (`quantityPlanLineId`) REFERENCES `mealquantityplanlines` (`quantityPlanLineId`),
  CONSTRAINT `productionplanlines_ibfk_3` FOREIGN KEY (`customerId`) REFERENCES `customers` (`customerId`),
  CONSTRAINT `productionplanlines_ibfk_4` FOREIGN KEY (`menuId`) REFERENCES `menus` (`menuId`),
  CONSTRAINT `productionplanlines_ibfk_5` FOREIGN KEY (`dishId`) REFERENCES `dishes` (`dishId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
