--
-- Table structure for table `productionplans`
--

DROP TABLE IF EXISTS `productionplans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `productionplans` (
  `planId` binary(16) NOT NULL,
  `planCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `planDate` date NOT NULL,
  `status` enum('CREATED','SENTTOKITCHEN','COMPLETED','CANCELLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CREATED',
  `createdBy` binary(16) NOT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `customerId` binary(16) DEFAULT NULL,
  `menuVersionId` binary(16) DEFAULT NULL,
  `weekStartDate` date DEFAULT NULL,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `sentToKitchenAt` datetime DEFAULT NULL,
  `sentToKitchenBy` binary(16) DEFAULT NULL,
  PRIMARY KEY (`planId`),
  UNIQUE KEY `planCode` (`planCode`),
  KEY `createdBy` (`createdBy`),
  KEY `customerId` (`customerId`),
  KEY `menuVersionId` (`menuVersionId`),
  KEY `sentToKitchenBy` (`sentToKitchenBy`),
  CONSTRAINT `productionplans_ibfk_1` FOREIGN KEY (`createdBy`) REFERENCES `users` (`userId`),
  CONSTRAINT `productionplans_ibfk_2` FOREIGN KEY (`customerId`) REFERENCES `customers` (`customerId`),
  CONSTRAINT `productionplans_ibfk_3` FOREIGN KEY (`menuVersionId`) REFERENCES `menuversions` (`menuVersionId`),
  CONSTRAINT `productionplans_ibfk_4` FOREIGN KEY (`sentToKitchenBy`) REFERENCES `users` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

