  `actionType` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sourceKey` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sourceSheet` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourceRow` int DEFAULT NULL,
  `businessKey` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `targetType` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `targetId` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reasonCode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `beforeEvidence` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `beforeHash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `afterEvidence` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `afterHash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `actionHash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`purchaseHistoryReconciliationActionId`),
  UNIQUE KEY `uqPurchaseHistoryReconciliationActionsRunAction` (`purchaseHistoryReconciliationRunId`,`actionId`),
  KEY `ixPurchaseHistoryReconciliationActionsHash` (`actionHash`),
  CONSTRAINT `purchasehistoryreconciliationactions_ibfk_1` FOREIGN KEY (`purchaseHistoryReconciliationRunId`) REFERENCES `purchasehistoryreconciliationruns` (`purchaseHistoryReconciliationRunId`) ON DELETE CASCADE,
  CONSTRAINT `ckPurchaseHistoryReconciliationActionsDisposition` CHECK ((`actionType` in (_utf8mb4'keep',_utf8mb4'version',_utf8mb4'deactivate',_utf8mb4'delete',_utf8mb4'block'))),
  CONSTRAINT `ckPurchaseHistoryReconciliationActionsSourceRow` CHECK (((`sourceRow` is null) or (`sourceRow` > 0)))
