  `asOfDate` date NOT NULL,
  `databaseFingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `backupIdentifier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `backupTargetFingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `restoreFingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `restoreVerified` tinyint(1) NOT NULL,
  `appliedBy` binary(16) NOT NULL,
  `appliedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `candidateCount` int NOT NULL,
  `currentUniqueBusinessKeyCount` int NOT NULL,
  `auditedDeltaCount` int NOT NULL,
  `actionCount` int NOT NULL,
  `blockerCount` int NOT NULL,
  `keepCount` int NOT NULL,
  `versionCount` int NOT NULL,
  `deactivateCount` int NOT NULL,
  `deleteCount` int NOT NULL,
