  CONSTRAINT `purchasehistoryreconciliationruns_ibfk_1` FOREIGN KEY (`appliedBy`) REFERENCES `users` (`userId`) ON DELETE RESTRICT,
  CONSTRAINT `ckPurchaseHistoryReconciliationRunsCounts` CHECK (((`candidateCount` >= 0) and (`currentUniqueBusinessKeyCount` >= 0) and (`auditedDeltaCount` >= 0) and (`actionCount` >= 0) and (`blockerCount` >= 0) and (`keepCount` >= 0) and (`versionCount` >= 0) and (`deactivateCount` >= 0) and (`deleteCount` >= 0) and (`blockCount` >= 0) and (`actionCount` = ((((`keepCount` + `versionCount`) + `deactivateCount`) + `deleteCount`) + `blockCount`)) and (`blockerCount` = `blockCount`))),
  CONSTRAINT `ckPurchaseHistoryReconciliationRunsRestoreVerified` CHECK ((`restoreVerified` = 1)),
  CONSTRAINT `ckPurchaseHistoryReconciliationRunsStatus` CHECK ((`status` in (_utf8mb4'APPLIED',_utf8mb4'NOOP')))
