--
-- Table structure for table `purchaseorders`
--

DROP TABLE IF EXISTS `purchaseorders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchaseorders` (
  `purchaseOrderId` binary(16) NOT NULL,
  `purchaseOrderCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `purchaseRequestId` binary(16) NOT NULL,
  `supplierId` binary(16) NOT NULL,
  `orderDate` date NOT NULL,
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ORDERED',
  `createdBy` binary(16) NOT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `proposedDeliveryDate` date DEFAULT NULL,
  `receivingWarehouseId` binary(16) DEFAULT NULL,
  `purchasingTerms` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  PRIMARY KEY (`purchaseOrderId`),
  UNIQUE KEY `purchaseOrderCode` (`purchaseOrderCode`),
  UNIQUE KEY `ixPurchaseOrdersCompatibility` (`purchaseRequestId`,`supplierId`,`proposedDeliveryDate`,`receivingWarehouseId`,`purchasingTerms`),
  KEY `IX_purchaseorders_createdBy` (`createdBy`),
  KEY `ixPurchaseOrdersRequest` (`purchaseRequestId`),
  KEY `ixPurchaseOrdersSupplier` (`supplierId`),
  CONSTRAINT `purchaseorders_ibfk_1` FOREIGN KEY (`purchaseRequestId`) REFERENCES `purchaserequests` (`purchaseRequestId`),
