  `evidenceId` binary(16) NOT NULL,
  `evidenceDate` date NOT NULL,
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `proposalFingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `proposalVersion` int NOT NULL,
  `requestedBy` binary(16) NOT NULL,
  `requestedAt` datetime NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `decidedBy` binary(16) DEFAULT NULL,
  `decisionReason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `decidedAt` datetime DEFAULT NULL,
  `supersededByExceptionId` binary(16) DEFAULT NULL,
  `concurrencyVersion` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`purchasePriceExceptionId`),
  UNIQUE KEY `uqPurchasePriceExceptionsProposal` (`purchaseLineSupplierDecisionId`,`proposalFingerprint`,`proposalVersion`),
  KEY `ixPurchasePriceExceptionsDecider` (`decidedBy`),
  KEY `ixPurchasePriceExceptionsRequester` (`requestedBy`),
  KEY `ixPurchasePriceExceptionsSupersededBy` (`supersededByExceptionId`),
