  CONSTRAINT `purchasepriceexceptions_ibfk_2` FOREIGN KEY (`requestedBy`) REFERENCES `users` (`userId`) ON DELETE RESTRICT,
  CONSTRAINT `purchasepriceexceptions_ibfk_3` FOREIGN KEY (`decidedBy`) REFERENCES `users` (`userId`) ON DELETE RESTRICT,
  CONSTRAINT `purchasepriceexceptions_ibfk_4` FOREIGN KEY (`supersededByExceptionId`) REFERENCES `purchasepriceexceptions` (`purchasePriceExceptionId`) ON DELETE RESTRICT,
  CONSTRAINT `ckPurchasePriceExceptionsDecisionComplete` CHECK ((((`status` = _utf8mb4'PENDING') and (`decidedBy` is null) and (`decisionReason` is null) and (`decidedAt` is null)) or ((`status` in (_utf8mb4'APPROVED',_utf8mb4'REJECTED')) and (`decidedBy` is not null) and (`decisionReason` is not null) and (`decidedAt` is not null)) or (`status` = _utf8mb4'SUPERSEDED'))),
  CONSTRAINT `ckPurchasePriceExceptionsStatus` CHECK ((`status` in (_utf8mb4'PENDING',_utf8mb4'APPROVED',_utf8mb4'REJECTED',_utf8mb4'SUPERSEDED'))),
  CONSTRAINT `ckPurchasePriceExceptionsStrictVariance` CHECK (((`referencePrice` > 0) and (`proposedPrice` > `referencePrice`) and (`variancePercent` > 15))),
  CONSTRAINT `ckPurchasePriceExceptionsSupersession` CHECK ((((`status` = _utf8mb4'SUPERSEDED') and (`supersededByExceptionId` is not null)) or ((`status` <> _utf8mb4'SUPERSEDED') and (`supersededByExceptionId` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
