DROP TABLE IF EXISTS `systemoperationmodes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `systemoperationmodes` (
  `id` tinyint unsigned NOT NULL,
  `mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` bigint NOT NULL,
  `updatedBy` binary(16) NOT NULL,
  `updatedAt` datetime NOT NULL,
  `reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `IX_systemoperationmodes_updatedBy` (`updatedBy`),
  CONSTRAINT `FK_systemoperationmodes_users_updatedBy` FOREIGN KEY (`updatedBy`) REFERENCES `users` (`userId`) ON DELETE RESTRICT,
  CONSTRAINT `ckSystemOperationModesSingleton` CHECK ((`id` = 1)),
  CONSTRAINT `ckSystemOperationModesToken` CHECK ((`mode` in (_utf8mb4'DEFAULT',_utf8mb4'MATERIAL_RECONCILIATION')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
